    },
    [15] = {
      beijing = 1123,
      dialog = 3,
      music = "48_Quiet_Daily",
      renwu = "npc",
      sentence = "I put a hand to my temple and thought back for a moment on all the banquets and parties we'd attended together. I'd practically never been pressured to drink by anyone.",
      next = {16}
    },
    [16] = {
      beijing = 1123,
      dialog = 3,
      music = "48_Quiet_Daily",
